from collections import Counter

def top_k_frequent(nums, k):
    buckets = [[] for _ in range(len(nums) + 1)]   # index = frequency
    for x, f in Counter(nums).items():
        buckets[f].append(x)
    res = []
    for f in range(len(nums), 0, -1):
        for x in buckets[f]:
            res.append(x)
            if len(res) == k:
                return res
    return res

