import random

def k_closest(points, k):
    dist = lambda p: p[0] * p[0] + p[1] * p[1]
    lo, hi = 0, len(points) - 1
    while lo < hi:                     # until slot k-1 holds its sorted value
        pivot = dist(points[random.randint(lo, hi)])
        lt, i, gt = lo, lo, hi         # 3-way partition: < pivot | == | >
        while i <= gt:
            d = dist(points[i])
            if d < pivot:
                points[lt], points[i] = points[i], points[lt]
                lt += 1
                i += 1
            elif d > pivot:
                points[gt], points[i] = points[i], points[gt]
                gt -= 1
            else:
                i += 1
        if k - 1 < lt:
            hi = lt - 1
        elif k - 1 > gt:
            lo = gt + 1
        else:
            break
    return points[:k]

