import heapq
from collections import Counter, deque

def least_interval(tasks, n):
    heap = [-c for c in Counter(tasks).values()]   # max-heap of counts left
    heapq.heapify(heap)
    cooling = deque()                  # (time it is ready again, -count)
    time = 0
    while heap or cooling:
        time += 1
        if heap:
            left = heapq.heappop(heap) + 1         # run the most frequent task
            if left:
                cooling.append((time + n, left))
        if cooling and cooling[0][0] == time:
            heapq.heappush(heap, cooling.popleft()[1])
    return time

