from collections import Counter

def least_interval(tasks, n):
    counts = Counter(tasks).values()
    f = max(counts)                             # max frequency
    c = sum(1 for x in counts if x == f)        # tasks tied at f
    return max(len(tasks), (f - 1) * (n + 1) + c)
